node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(ws);

// Key metrics
const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = data.reduce((s,r) => s + r['Total Paid'], 0);
const confirmedRevenue = confirmed.reduce((s,r) => s + r['Total Paid'], 0);
const cancelledRevenue = cancelled.reduce((s,r) => s + r['Total Paid'], 0);

// Unique customers
const customers = [...new Set(data.map(r => r.Customer))];

// Top customers by confirmed revenue
const custRevenue = {};
confirmed.forEach(r => { custRevenue[r.Customer] = (custRevenue[r.Customer]||0) + r['Total Paid']; });
const topCust = Object.entries(custRevenue).sort((a,b)=>b[1]-a[1]).slice(0,5);

// Date range
const dates = [...new Set(data.map(r => r.Date))].sort();

// Popular items
const itemCount = {};
confirmed.forEach(r => {
  r.Items.split(', ').forEach(item => { itemCount[item] = (itemCount[item]||0) + 1; });
});
const topItems = Object.entries(itemCount).sort((a,b)=>b[1]-a[1]).slice(0,5);

console.log('=== Metrics ===');
console.log('Total orders:', totalOrders);
console.log('Confirmed:', confirmed.length);
console.log('Cancelled:', cancelled.length);
console.log('Total revenue (all):', totalRevenue);
console.log('Confirmed revenue:', confirmedRevenue);
console.log('Cancelled value:', cancelledRevenue);
console.log('Unique customers:', customers.length);
console.log('Date range:', dates.join(' to '));
console.log('Avg confirmed order:', (confirmedRevenue/confirmed.length).toFixed(2));
console.log('Top customers:', JSON.stringify(topCust));
console.log('Top items:', JSON.stringify(topItems));
"

